CREATE FUNCTION initialize_room_checklist() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN INSERT INTO public.room_checklists(organization_id,property_id,room_id) VALUES(NEW.organization_id,NEW.property_id,NEW.id);RETURN NEW;END $$;
CREATE TRIGGER initial_checklist AFTER INSERT ON rooms FOR EACH ROW EXECUTE FUNCTION initialize_room_checklist();REVOKE ALL ON FUNCTION initialize_room_checklist() FROM PUBLIC;
CREATE FUNCTION inventory_entitlement_summary(org uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE e public.organization_entitlements%ROWTYPE;label text;effective text;BEGIN IF org IS DISTINCT FROM public.current_org() OR NOT public.is_org_owner(org) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;SELECT * INTO e FROM public.organization_entitlements WHERE organization_id=org;IF NOT FOUND THEN RETURN jsonb_build_object('configured',false);END IF;SELECT p.label INTO label FROM public.saas_plans p WHERE p.id=e.plan_id;effective:=e.state;IF e.state NOT IN ('restricted','cancelled') AND e.valid_until IS NOT NULL AND clock_timestamp()>=e.valid_until THEN effective:=CASE WHEN e.grace_until IS NOT NULL AND clock_timestamp()<e.grace_until THEN 'grace' ELSE 'restricted' END;END IF;IF e.state='grace' AND(e.grace_until IS NULL OR clock_timestamp()>=e.grace_until) THEN effective:='restricted';END IF;RETURN jsonb_build_object('configured',true,'planLabel',label,'kind',e.plan_kind,'state',effective,'roomLimit',e.room_limit,'propertyLimit',e.property_limit,'staffLimit',e.staff_limit,'roomsUsed',(SELECT count(*) FROM public.rooms WHERE organization_id=org AND archived_at IS NULL),'propertiesUsed',(SELECT count(*) FROM public.properties WHERE organization_id=org AND archived_at IS NULL),'staffUsed',(SELECT count(*) FROM public.memberships WHERE organization_id=org AND revoked_at IS NULL),'version',e.version);END $$;
REVOKE ALL ON FUNCTION inventory_entitlement_summary(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION inventory_entitlement_summary(uuid) TO kost_app;
